// ❌ Traditional class with boilerplate
public class Person
{
    public string FirstName { get; }
    public string LastName { get; }
    public int Age { get; }

    public Person(string firstName, string lastName, int age)
    {
        FirstName = firstName;
        LastName = lastName;
        Age = age;
    }

    // Need to override Equals, GetHashCode, ToString...
}

// ✅ Record - concise, immutable, value-based equality
public record Person(string FirstName, string LastName, int Age);

// Usage
var person1 = new Person("John", "Doe", 30);
var person2 = new Person("John", "Doe", 30);

Console.WriteLine(person1 == person2); // True (value-based equality)
Console.WriteLine(person1); // Person { FirstName = John, LastName = Doe, Age = 30 }

// With-expression for non-destructive mutation
var olderPerson = person1 with { Age = 31 };
Console.WriteLine(person1.Age); // 30 (unchanged)
Console.WriteLine(olderPerson.Age); // 31 (new record)

// Relational patterns
public string GetGrade(int score) => score switch
{
    >= 90 => "A",
    >= 80 => "B",
    >= 70 => "C",
    >= 60 => "D",
    _ => "F"
};

// Logical patterns
public bool IsValid(User user) => user switch
{
    { IsActive: true, Age: >= 18 and < 65 } => true,
    _ => false
};

// List patterns (C# 11+)
public int Sum(List<int> numbers) => numbers switch
{
    [] => 0,
    [var first] => first,
    [var first, .. var rest] => first + Sum(rest.ToList())
};

// Property patterns
public string FormatAddress(Address address) => address switch
{
    { Country: "US" } => $"{address.City}, {address.State} {address.Zip}",
    { Country: "CA" } => $"{address.City}, {address.Province} {address.Postal}",
    _ => $"{address.City}, {address.Country}"
};

// Generator attribute
[AttributeUsage(AttributeTargets.Class)]
public class AutoNotifyAttribute : Attribute { }

// Generator implementation (simplified)
[Generator]
public class AutoNotifyGenerator : ISourceGenerator
{
    public void Execute(GeneratorExecutionContext context)
    {
        var compilation = context.Compilation;
        var receiver = context.SyntaxReceiver as AutoNotifyReceiver;

        foreach (var classSyntax in receiver.CandidateClasses)
        {
            var model = compilation.GetSemanticModel(classSyntax.SyntaxTree);
            var classSymbol = model.GetDeclaredSymbol(classSyntax);

            var source = GenerateNotifyPropertyChanged(classSymbol);
            context.AddSource($"{classSymbol.Name}_AutoNotify.g.cs", source);
        }
    }

    private string GenerateNotifyPropertyChanged(INamedTypeSymbol classSymbol)
    {
        // Generate INotifyPropertyChanged implementation
        return $"// Auto-generated code
partial class {classSymbol.Name} : INotifyPropertyChanged
{{
    public event PropertyChangedEventHandler PropertyChanged;
    protected void OnPropertyChanged([CallerMemberName] string propertyName = null)
    {{
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }}
}}";
    }
}

// Expression-bodied members
public class Calculator
{
    public int Add(int a, int b) => a + b;
    public int Multiply(int a, int b) => a * b;
}

// Local functions for encapsulation
public IEnumerable<int> GetPrimes(int max)
{
    bool IsPrime(int n)
    {
        if (n < 2) return false;
        for (int i = 2; i <= Math.Sqrt(n); i++)
        {
            if (n % i == 0) return false;
        }
        return true;
    }

    return Enumerable.Range(2, max).Where(IsPrime);
}

// Pipelining with method chaining
public string ProcessText(string input) => input
    .Trim()
    .ToLower()
    .Split(' ')
    .Where(word => word.Length > 3)
    .OrderBy(word => word)
    .Aggregate((a, b) => $"{a}, {b}");

// Option/Maybe pattern with records
public record Option<T>(T Value, bool IsSome);

public static class OptionExtensions
{
    public static Option<T> Some<T>(T value) => new(value, true);
    public static Option<T> None<T>() => new(default, false);

    public static Option<TResult> Map<T, TResult>(
        this Option<T> option, 
        Func<T, TResult> mapper) => 
        option.IsSome ? Some(mapper(option.Value)) : None<TResult>();
}

